// generated by tools/voices/build_npcs.py from src/npcs/*.md — round 133, the backstories for everyone else (do not edit by hand)
var ZNPC={"primrose":{"who":"Primrose","group":"fairies","realm":1,"fairy":0,"spirits":["Asa","Bersi"],"lines":{"before":["Asa is chained at the old Fernby stone. Morning is her story time. Do not be late — she hates when I am late.","Bersi was going to be a shipwright. He drew boats in the dirt for me. Thirty-six winters of boats, and not one of them ever got wet.","They will not know you. Say my name first. Then say \"Fernby\". Then whatever else you like.","I tried to bite the chain once. Fairy teeth are for honey. I do not recommend it.","Asa wove twenty shawls for babies that never came. She is not sad about it any more. I am, a little, for her."],"after":["Asa came to my stone this morning and told her story at exactly the right time. I cried. Do not tell her.","Bersi wants to see the lake. I told him boats float on it. He did not believe me, so I showed him. He has not stopped grinning.","They do not need my schedule any more. I made a new one anyway. It has more naps in it.","When they rose I tidied the stone. It did not need tidying. I just did not know what to do with my hands.","Now that they are free, who do I sing to at dusk? You, I suppose. Stand still."],"life":["I am the first fairy of the Grasslands. That means I was here first. It does not mean I am the oldest. Never say I am the oldest.","Before the quiet, carts stopped at my stone and the farmers left a crust for me. I miss the crusts more than I should.","I slept in a primrose for eleven winters. Yellow is a very loud colour to sleep inside.","Clover is my sister-fairy. She counts leaves. I count everything else.","The moss on the runes grows back every morning. I scrape it off every morning. We have an understanding, the moss and I.","I am not afraid of wolves. I am afraid of being forgotten. Wolves are just very large and rude."],"stage2":["The carts are coming back to the crossroads. One farmer left a whole bun. I have named him my favourite person."],"stage3":["I flew to the next stone today and back. It took all morning. I used to do it before breakfast. I am out of practice at being free."],"stage4":["Fernby has smoke in a chimney again. Only one chimney. That is how everything starts."],"stage5":["The fields are full of children's voices. I have made a schedule for them. They do not follow it. I love them anyway."]}},"bramble":{"who":"Bramble","group":"fairies","realm":1,"fairy":1,"spirits":["Dagny","Eyvind"],"lines":{"before":["Dagny and Eyvind. Married. Bound a hill apart, and each can see the other's light. That is the cruellest thing I know.","I carried one word a night between them. Thirty-six winters of words. Most of them were \"still here\".","Eyvind mended nets and told lies about fish. Dagny mended nets and told the truth about everything. They were very happy.","Free Dagny first, or Eyvind first — it does not matter. Just free them on the same day. Promise me.","Do not ask me what Dagny saw on the water that night. That is hers to tell."],"after":["They walked to each other the moment the chains fell. Neither of them said anything. They did not need to; I had carried enough words.","Eyvind asked me for one more message. I said, \"She is standing right there.\" He said, \"I know. Tell her anyway.\"","I have no letters to carry now. My wings feel strange. Light. Useless. Lovely.","Dagny told you what she saw, did she not? Good. Now you know why I am fond of you.","Stonewick's lake path is just a path again. I walk it on foot sometimes, to feel ordinary."],"life":["I am called Bramble because I am sharp and I hold on. Both are compliments. Say thank you.","The fishers used to leave a sprat on my stone at dawn. I do not eat sprats. I liked that they remembered.","Primrose makes schedules. I make thorns. Between us the Grasslands got through.","I fought a crow once, for a button. I won. The crow will tell you otherwise. The crow is a liar.","I was not afraid in the dark. I was angry in the dark. Anger lasts longer."],"stage2":["The lake is giving fish again. The fishers are back at dawn. One of them left a sprat. I still do not eat sprats. I said thank you anyway."],"stage3":["Stonewick's nets are hung out to dry on the wall again. Dagny inspects every one. Nobody dares tie a bad knot near her."],"stage4":["I flew to the top of the hill between their stones today. You can see the whole lake from there. They should build a bench. I will tell Bram."],"stage5":["There is a baby in Stonewick called Bramble. Her mother says it is after the hedge. I know better."]}},"clover":{"who":"Clover","group":"fairies","realm":1,"fairy":2,"spirits":["Frida","Geir"],"lines":{"before":["Frida had forty-one hives. On the morning the sky went quiet there were forty-one, and by dusk there were none. I counted.","Geir carved the tree on your Green when he was a boy. He is very proud of the roots. Ask him about the roots. Then sit down; it takes a while.","Thirteen thousand one hundred and forty-something days. I lost count once, in the sixth winter. It frightened me more than the Binders.","Frida asks me every evening if the bees are back. Every evening I say \"not yet\". I would like to say something else.","Geir carves in the air with his fingers when he thinks nobody is looking. He is carving the same thing over and over: a door."],"after":["The bees came back the morning after Frida rose. All forty-one hives' worth. I counted twice to be sure.","Geir asked to see the Green. He looked at the tree he carved for a very long time and said, \"The roots go further than anyone thinks.\"","I have stopped counting days. Now I count bees. It is much more cheerful, and they hold still less.","Frida gave me a drop of the first honey. It is the best thing I have ever tasted, and I have tasted dew.","Geir is carving a real door now, in Hollowmere. He will not say where it goes. I think it goes home."],"life":["I count things. Leaves, bees, steps, stars. If I can count it, it is real. If I cannot count it, I worry.","Four. A clover has four leaves. Always four. That is the most comforting number there is.","I told the village the bees were leaving. Nobody listens to a fairy counting bees. They should.","Primrose says I worry too much. Primrose was asleep in a flower for eleven winters. I was awake for all of mine.","The orchards above Hollowmere had nine hundred and twelve trees. Three hundred are still standing. I visit each one."],"stage2":["The orchard has blossom on a hundred and six trees. Last spring it was none. I am trying very hard not to count it again."],"stage3":["Frida has started a forty-second hive. She says it is for luck. Luck does not need honey. I let her have it."],"stage4":["Geir's door in Hollowmere has a carved tree on it. The roots go all the way to the hinges."],"stage5":["I counted the children on the Green today. I got a different number every time. They keep moving. It is wonderful."]}},"linnet":{"who":"Linnet","group":"fairies","realm":1,"fairy":3,"spirits":["Hallveig","Ingolf"],"lines":{"before":["Hallveig is Rolf's wife. Yes, that Rolf. He still sets two cups out at the tavern. She knows. I told her.","Ingolf talks about the Binders a great deal. He learned things, chained there. Listen to him. Then do not listen too long.","I sing to them every night. The old songs, the ones for the road up. They cannot take the road. They can still have the songs.","Hallveig's laugh is the loudest thing on the Downs. Even in chains. Especially in chains.","Ingolf says the Binders do not come from the Ashlands but from under it. He says it the way you say a thing you wish you had not learned."],"after":["Hallveig went straight to the tavern. Rolf dropped both cups. Nobody has ever seen the tavern so quiet, or so loud right after.","Ingolf is tanning hides again in Stonewick. He keeps the windows open. He says he has had enough of the dark for one lifetime.","I sang the road-song when they rose. My first time singing for someone who could answer. Hallveig sang the harmony. Badly. Perfectly.","Rolf brought me a thimble of mead. I am a very small fairy. I was very happy for the rest of the day.","Now that they are home, I sing for the stone. It does not clap, but it hums back."],"life":["I know every song the Downs ever sang over the dead. Two hundred and six. Clover counted them for me.","I have never sung for anyone alive. If you ask me to, I will turn red and fly into a hedge.","A linnet is a small brown bird with a red cap that sings more than it should. I chose my name very carefully.","The barrows on the Downs are old, older than the stones. The dead there were already home when the gate shut. I envy them.","When the Binders came along the road, I hid in the long grass and sang very, very quietly. They did not hear. Or they did not care."],"stage2":["A shepherd on the Downs was whistling one of my songs today. Wrong, but recognisably. I nearly fell off the stone."],"stage3":["Hallveig has taught the whole tavern the harmony to the road-song. They sing it at closing. I sit on the rafter and listen."],"stage4":["The road up the Downs is green again. When the road up the Tree opens too, I will sing every one of the two hundred and six. All the way."],"stage5":["I sang for the children on the Green today. In front of everyone. I went red. They clapped. I would like to do it again tomorrow."]}},"sorrel":{"who":"Sorrel","group":"fairies","realm":1,"fairy":4,"spirits":["Jorunn","Ketil"],"lines":{"before":["Thirty-six winters I slept in a clover. Do you know how small a clover is? I counted its leaves every morning to be sure I was still there.","Jorunn could match any blue in the world. I describe the sky to her every morning so she does not forget which one is hers.","Ketil's goats cried for a whole winter after he died. Then they wandered off. I do the goat voices for him. He says I am terrible at it.","They are tired, my two. Not sad. Tired is worse, I think. Sad still wants something.","If you are frightened of the Binder, say so. Saying it out loud makes it smaller. That is the only magic I have."],"after":["Jorunn stood in the dye-pools up to her knees and looked at the sky until it got dark. She says the blue is right. I knew it would be.","Ketil has found three goats already. They are not his goats. He says that does not matter; goats are goats.","I do not have to do the goat voices any more. I still do them. Ketil still says I am terrible. He laughs every time.","When they rose, they were not tired any more. They wanted things. Breakfast. Goats. Blue. That is how I knew they were alive in the way that counts.","I slept in a real bed of moss last night, not a clover. It was too big. I have gone back to the clover."],"life":["Four. Always four leaves. That is the only reason I am still me.","I am the smallest fairy in the Grasslands. The others say \"smallest\" like it means \"least\". It means \"hardest to catch\".","Sorrel is a leaf that tastes sour. I chose it so nobody would try to eat me.","When I am frightened I say the frightening thing out loud. \"The Binder is very large.\" See? Now he is only large.","The dye-pools by the Fernby water are every colour at once when the sun hits them. That is my favourite thing in the realm."],"stage2":["The dye-pools are being used again. Somebody in Fernby is wearing Jorunn's blue. I followed them for a mile to look at it."],"stage3":["Ketil's goats have had kids. Goat kids, not the other sort. He has named one after me. It eats everything. I am flattered."],"stage4":["The other fairies talk about the gate opening as if it is a door. I think it will be more like waking up. You do not open waking up."],"stage5":["I have stopped counting the leaves. I still know there are four. It is enough to know."]}},"lily":{"who":"Lily","group":"fairies","realm":2,"fairy":0,"spirits":["Liv","Magni"],"lines":{"before":["Liv was at the wheel when it turned backwards. She still hears it. I hum over the sound for her, every night.","Magni built the dikes. He thinks the Tide came because his wall was not high enough. It came up from under. Nothing would have been high enough.","I tell Magni it was not his fault. Every day. Some days he nearly believes me. Those are good days.","Millbrook is under the reeds now. You can still see the top of the wheel when the water is low. Do not look at it too long.","They are kind to each other, my two. Liv brings Magni the songs of the river. Magni builds Liv little walls of pebbles. In chains. Still."],"after":["Liv went straight to the river and put her hand in it. It ran the right way. She laughed until she cried.","Magni looked at the dikes for a long time. Then he said, \"I could make them better.\" That is the first time in thirty-six winters he has wanted to build anything.","The mill wheel is coming up out of the reeds. Bram helped. Magni would not let him do the stonework.","I have nothing to hum over any more. I hum anyway. Habit.","When they rose, Magni said, \"It was not my fault.\" Not to me. To himself. I have been waiting thirty-six winters for him to say that."],"life":["I ride a lotus petal. It is the most comfortable thing in the world, and it never sinks if you are kind to it.","My hair is a little waterfall. In winter it freezes and I am a very quiet fairy for a while.","I am calm because the Wetlands needed someone to be. Everyone else was busy drowning.","I have never raised my voice. I do not know if I can. I am a little afraid to find out.","The other Wetlands fairies call me \"the Pond\". I do not mind. Ponds are deep."],"stage2":["The Silverrun runs clear past Millbrook. There is a heron fishing where the mill-race was. I have asked him to move. He has not."],"stage3":["The mill wheel turns again. The right way. Liv grinds the first flour herself. It is grey and gritty and the best bread in Runeheim."],"stage4":["Magni is building a new dike, very low. Not to keep the water out. Just to sit on and watch it."],"stage5":["Children paddle in the mill-race now. Liv shouts at them to be careful. Then she joins in."]}},"marsh":{"who":"Marsh","group":"fairies","realm":2,"fairy":1,"spirits":["Nanna","Oddny"],"lines":{"before":["Nanna was a midwife for eight years with nothing to catch. Then the Tide came. You can imagine. Do not imagine too hard.","Oddny's urns never cooled. That is how I knew. The dead were not leaving. They were stuck, keeping the clay warm.","The Binder at their stone used to run the Reedhaven ferry, they say. He took the fire-giant's coin and stopped asking where the boat went.","I expect you will fail. I expect it of everyone. It is not personal. It is the Wetlands.","If you do free them, I will expect them to be miserable. If they are not, I will be very pleasantly surprised."],"after":["You did it. I am very pleasantly surprised. Do not get used to it.","Oddny touched an old urn and it went cold in her hands. She sat down in the reeds and laughed like a girl.","Nanna keeps looking at her hands. She says they are ready. I asked, \"Ready for what?\" She smiled and would not say.","I tried to expect the worst today and could not think of anything. It was very unsettling.","Reedhaven had three thousand people. Now it has reeds. But the reeds are green. I will take green."],"life":["I am the gloomiest fairy in Runeheim. I have checked. The others are all ridiculously hopeful.","Say the worst thing first, and it cannot ambush you. That is my whole philosophy. It fits on a reed.","Lily is calm. Ripple is cheerful. Nixie rings bells. I wait for things to go wrong. Every family needs one.","I like fog. It hides everything, so nothing can disappoint you.","I have a frog. Its name is Frog. It is the most reliable friend I have ever had."],"stage2":["The reed-beds are full of birds again. Loud ones. I did not ask for this. I like it."],"stage3":["Somebody is building in Reedhaven. Small houses on stilts. They will probably flood. I hope they do not."],"stage4":["Oddny is making new urns. Not for the dead. For flowers. She says the dead will not need them now. I think she is right. I hate being hopeful."],"stage5":["Nanna's hands are full now. She does not stop smiling. Neither do I, and I have tried."]}},"ripple":{"who":"Ripple","group":"fairies","realm":2,"fairy":2,"spirits":["Ragna","Sigrid"],"lines":{"before":["Ragna was a shepherd girl. She thinks the sky is not angry, just sad. I think she is cleverer than most grown-ups.","Sigrid took the Binders' gold, once. Muspelheim gold. That is how it starts, she says. She says it every day, as if I might forget.","I make Ragna laugh with ripples. Like this. See? Well, imagine it in the dark, with chains. It still works.","Sigrid will not look at you. Not because of you. Because of the gold. Be patient with her.","Hverholm's walls held the river out for a hundred years. The Tide came up through the floors. The walls are still standing. That is almost worse."],"after":["Ragna rose giggling. She asked if the sheep were all right. I said there are new sheep. She said that will do.","Sigrid stood at the forge in Hverholm a long time. Then she lit it. She is making horseshoes. \"Something useful,\" she says. \"Something honest.\"","I skipped across the whole Silverrun today and back. Nobody needed cheering up. I did it for fun. Imagine that.","Sigrid looked at me today. At me. And said thank you. I fell off the water.","Ragna wants to know if the sky is still sad. I told her to look up. She says it looks better. So do I."],"life":["I am the cheerful one. It is not easy. You have to practise every morning, like a song.","When I am frightened, I skip across the water. If you see ripples on a still pond, that was me, being brave.","Hverholm was a town of walls and bells and ducks. The ducks are back. The bells are Nixie's business.","I keep a pebble from every stone in the Wetlands. Fifty-three. They are all slightly wet.","Marsh says I am ridiculously hopeful. I say Marsh is secretly hopeful and very bad at hiding it."],"stage2":["The ducks of Hverholm have come home. They are as rude as ever. I am delighted."],"stage3":["Sigrid's horseshoes are on every horse in the Wetlands. Hana says they are the best she has ever seen. Sigrid blushed. Smiths do not blush. She did."],"stage4":["Ragna asked me what is past the Ember Wall. I said fire. She said, \"And after that?\" I did not know. You will find out."],"stage5":["There is a new shepherd girl on the hill by Hverholm. Ragna sits beside her every evening and teaches her the songs."]}},"nixie":{"who":"Nixie","group":"fairies","realm":2,"fairy":3,"spirits":["Torvi","Ulf"],"lines":{"before":["I rang the drowned bells every night. Every one. Thirty-six winters. My arms are very strong for a fairy. Feel. No, do not.","Torvi heard the trees whisper a name. She will not say it to me. She says it is not a name for small creatures.","Ulf brewed the best mead on the Lantern Isles. One year the cup turned to ash. He has not trusted a cup since.","WHAT? Sorry. The bells. I do not hear very well. Say it again, louder, and with your hands.","The Binders hate the bells. That is why I rang them. Anything a Binder hates is worth doing twice."],"after":["Torvi went into the marsh trees and listened. She says they are whispering something else now. A kinder thing. She will not say that either.","Ulf brewed a little mead and poured the first cup on the ground. It did not turn to ash. He sat with it a long time.","I do not have to ring the bells any more. I rang them anyway, once, to say they were free. The whole marsh heard.","My arms are tired for the first time in thirty-six winters. I am going to let them be tired.","The Lantern Isles are coming up out of the water, one roof at a time. The bells were still there. Of course they were. I kept them."],"life":["I never slept. Not once. Lily slept on her petal. Marsh slept in fog. I rang bells.","Nixie means a water-sprite who drags sailors under. I have never dragged anyone. I have rescued four. Ask the herons.","I am loud because the bells are louder. You would be loud too.","I like thunderstorms. They are the only thing that can out-ring me.","If you ever hear a bell under water, wave. It is probably me, saying hello."],"stage2":["The Lantern Isles' lights are lit again. One lantern per house. There are eleven houses so far. I have counted the lanterns more than once."],"stage3":["Ulf has opened a little mead-house on the first isle. He calls it The Bell. I asked him why. He winked."],"stage4":["Torvi says the trees have stopped whispering the dark name. They are whispering yours now. Do not let it go to your head."],"stage5":["The bells ring at every wedding on the isles. I ring them. Nobody has asked me to stop. I will not stop."]}},"fenna":{"who":"Fenna","group":"fairies","realm":2,"fairy":4,"spirits":["Vigdis","Yrsa"],"lines":{"before":["Vigdis knows every saga ever sung, except one verse. The one about the high seat. It drives her mad. It drives me mad too, and I am very patient.","Yrsa baked bread for the midsummer feast every year. The last year, nobody came down to take it up. She left it on the hill. It is still there in her mind.","Vigdis and I argue about verses. I am usually right. She is usually louder. In a saga, louder wins.","Yrsa describes bread to me every night. I have never eaten bread. I am an expert anyway.","The missing verse. If you ever find it, tell Vigdis before you tell anyone. She has earned it."],"after":["Vigdis rose reciting. She has not stopped. She has a great deal to catch up on, and an audience at last.","Yrsa went straight to an oven in the nearest standing house and baked. I have now tasted bread. I was right about everything.","Vigdis says she will find the missing verse herself now. I believe her. I also believe your twin will find it first. Do not tell her I said so.","Yrsa left a loaf on the hill again, for midsummer. \"In case,\" she said. I did not ask in case of what.","My stone has never been so quiet. Vigdis is reciting in the village now. I miss the arguing. I have started arguing with herons."],"life":["I have read everything that ever floated past my stone. Recipes, letters, half a saga, three tax-rolls and a love poem to a goat.","Fenna is the fen — the wet, flat, patient land. I am patient. I am also usually right, which makes the patience hard.","I keep the floating pages in a dry hollow under the stone. It is the only library in the Wetlands. You may visit. Wipe your feet.","I do not like fire. I have too many pages.","The love poem to the goat is quite good. I think the goat said yes."],"stage2":["Vigdis has taken three apprentices in the village. Grown men, all of them, and she makes them recite until they weep. They come back every day."],"stage3":["Yrsa sent bread up the hill at midsummer and it was gone in the morning. She thinks it was a fox. I have my own theory. I am keeping it."],"stage4":["I have started writing the Wetlands' own saga, from the pages I saved. Vigdis says my verses are too long. Vigdis is not wrong."],"stage5":["Vigdis has the missing verse now. She recited it on the Green and nobody breathed. I cried on my lotus. Lily says I made the pond salty."]}},"flint":{"who":"Flint","group":"fairies","realm":3,"fairy":0,"spirits":["Arnor","Bodil"],"lines":{"before":["Arnor heard the stone singing. So did I. I told the miners. Nobody listens to a fairy who sparks when she talks.","Bodil built ships on a mountain. For a sea she could see from the peaks. That is the bravest foolish thing I have ever known.","I strike sparks to keep them warm. All night. Every night. My knuckles are very sore. Do not hold my hand.","Do not listen if the stone sings to you down there. It sings the same song it sang to Deepdelve.","Arnor weaves in the air with his fingers. Miners' cloth. Thick, grey, warm. He is weaving for men who are not coming home."],"after":["Arnor asked about the miners. I told him some of them are spirits too, in the other realms' stones. He has gone looking.","Bodil climbed to the highest peak and looked west. The sea is still there. She says the road to it can be mended. Mira says the same.","I stopped striking sparks. It is cold. I like it. Cold means nobody needs me to be warm for them.","Deepdelve is still a hole in the mountain. Arnor says holes can be filled with better things. I do not know what he means. I hope he does.","When they rose, the stone hummed. Not sang. Hummed. A good sound. I have been listening to it all week."],"life":["I am called Flint because I spark when I am cross, and I am cross a great deal.","I heard the singing first. I knew first. Being right first is lonely.","Crystal pixies are hard to break. That is a good thing to be, in the Highlands.","I keep a piece of the old Deepdelve gate in my stone. Black iron. I do not know why. I cannot let go of it.","Aster says I should strike fewer sparks and talk more softly. Aster has never had to keep two people warm all night."],"stage2":["The Highland lift runs. Mira's cage rattles past my stone every morning. I spark at it. It is our greeting."],"stage3":["Bodil's first new boat is finished. It is on top of a mountain. She says it is \"waiting\". I like her more every day."],"stage4":["The stone in Deepdelve has stopped singing. Arnor went down to listen. He came up smiling. He would not say why."],"stage5":["Bodil's boat is on the western sea at last. She sent a message back with a gull. The gull bit me. Worth it."]}},"aster":{"who":"Aster","group":"fairies","realm":3,"fairy":1,"spirits":["Dalla","Einar"],"lines":{"before":["Einar used to see the white city in the mountain lakes on still nights. Then one night only a golden mask, looking back up at him. He has not looked since.","Dalla knows of a chamber under the mountains where light is chained. She will tell you. Listen closely. It matters.","I tell them stories with happy endings. Every night. They say I am childish. They listen to every word.","Kettlecrag fished the high lakes for a thousand years. The fish are still there. Nobody to catch them.","If you find the chained light, be kind to it. Dalla says it has been afraid for a very long time."],"after":["Einar looked into the mountain lake last night. Just his own face. He said that was enough for now.","Dalla told you about the chamber. Then she sat down and slept for a whole day. Some things are heavy to carry until you hand them over.","I told them a story when they rose. It had a happy ending. This time it was true.","Kettlecrag has a boat on the lake again. One boat. Einar's. He does not fish. He just floats.","I do not have to make up happy endings now. You are making one. Do not stop."],"life":["Aster means star. I am a very small star. I do my best.","Flint sparks. I glow. Between us, the Highlands are well lit.","I believe that if you end a story well, the world listens. I have no proof. I do not need any.","I once tried to tell a Binder a story. He did not stop to listen. I told it anyway, to his back. I hope some of it got in.","I am afraid of the dark under the mountains. That is why I sit at the top of them."],"stage2":["The Wetlands' bells rang all night when the Highland lift opened. Nixie, probably. I could hear them from here. I cried a little."],"stage3":["Einar caught a fish today. He let it go. He says the lake has done enough giving for a while."],"stage4":["Dalla went down to the chamber under the mountains. It is empty now. The light is gone. Gone home, she says."],"stage5":["On still nights the white city shows in the mountain lakes again. Einar takes his whole village out on the water to see it."]}},"quartz":{"who":"Quartz","group":"fairies","realm":3,"fairy":2,"spirits":["Gudrun","Hakon"],"lines":{"before":["Hakon says every rune in the mountains points to the lake. He is right. I have mapped all of them. Two hundred and eight, all pointing home.","Gudrun's queen bee was golden. The Binders crushed her first. Gudrun has not said a sharp word since. That is how I know how angry she is.","I answer fear with lists. Here is today's: Binder, chain, cold, stone. Now it is a list. Lists can be crossed off.","Highmark stood on the cliff road to the western sea. The road broke in the Stone-Fall. The town held on to the cliff a while. Then it did not.","If you free Hakon, ask to see the rune map. Then you will understand why the lake matters so much."],"after":["Hakon and I finished the rune map. Two hundred and nine. We had missed one, under a waterfall. He found it on his first day free.","Gudrun has bees again — wild ones, from the high meadows. She has not found a golden queen. She says she does not need one now.","I made a list when they rose. It said: free. That is all. One word. The best list I have ever made.","Highmark is a ruin on a cliff. Bodil says the sea-road can be mended. I have started a list of what that needs. It is long.","The runes point to the lake. You are from the lake. I have added you to the map."],"life":["You can see right through me. That makes me very bad at secrets and very good at windows.","Quartz is the commonest crystal in the mountains. Common things hold the world up.","I have a map of every rune in the Highlands, every stone, every spring and every hiding place. It took thirty-six winters. Ask, if you get lost.","I do not like surprises. I like lists. Surprises are things that are not on lists yet.","Heather says I should feel things more. I do feel things. I just write them down first."],"stage2":["I have added the lift to the map. And Mira. And Mira's hat. It is a very good hat."],"stage3":["Gudrun's wild bees have made honey that tastes of snow. I did not know honey could do that. It is now on my list of good things."],"stage4":["The rune map shows a new line, faint, running from the lake to the Ashlands. It was not there before. It is a soul-line. Yours."],"stage5":["The sea-road to Highmark is open. I walked it with Bodil and Hakon. I crossed off the last thing on the list. I cried. That was not on the list."]}},"heather":{"who":"Heather","group":"fairies","realm":3,"fairy":3,"spirits":["Ingrid","Joreid"],"lines":{"before":["Joreid was the last child born in the Highlands. She lived three summers. She has been three summers old in chains for thirty-six winters.","I made her a garden in the shadow of the stone, out of moor-flowers. She names every one. Some of the names are very rude.","Ingrid saw the Scar split. She says the mountain was answering the fire. She is old and she is right about most things.","I am afraid of the day you free them. Joreid will be free to go up the Tree. I want that. I do not want it. Both.","Ingrid keeps Joreid warm with stories of barrels. Joreid finds barrels very boring. She listens anyway. That is love."],"after":["Joreid ran. Three summers old and thirty-six winters chained, and the first thing she did was run, straight through my garden. I have never seen anything better.","Ingrid sat on the moor and watched the Scar for a long time. Mira's lift went past. Ingrid said, \"Well. The mountain answered. Now we have.\"","Joreid has not gone up the Tree yet. She says she is waiting for the road to be ready. I think she is waiting for me to be ready.","I am trying to be ready. It is the hardest thing I have ever tried.","Ingrid made Joreid a tiny barrel. Joreid says it is the least boring barrel in the world. Ingrid has never been so proud."],"life":["I am heather: small, purple and stubborn enough to grow on a mountain. Most people think I am soft. They are half right.","I feel things first and think about them later. Quartz does it the other way round. We argue beautifully.","The moor where I keep my stone is where the Kettlecrag families buried their own. I know every name on every cairn.","My garden in the stone's shadow has thirty-one kinds of flower. Joreid named all of them. \"Sir Bossy\" is a thistle.","If I could have one wish, it would be for Joreid to grow up. I know I cannot have it. I wish it anyway, every night."],"stage2":["The lift has brought visitors to the moor. They left flowers on the cairns. I know whose. I thanked them, though they could not hear me."],"stage3":["Joreid has taught the wild goats to follow her. Ingrid says they will eat my garden. Ingrid is right. I do not mind."],"stage4":["The road up the Tree will open soon, Joreid says. She asked if I would walk her to the bottom of it. I said yes. I will."],"stage5":["Joreid went up the Tree with the others, holding my hand to the very first bough. She waved. There are children on the moor now. I tend their gardens too."]}},"tor":{"who":"Tor","group":"fairies","realm":3,"fairy":4,"spirits":["Kolbein","Lofn"],"lines":{"before":["Lofn saw two ravens circle the hills, crying, the year the gate shut. All the others had gone. Those two stayed. She watches for them still.","Kolbein will tell you something about the one on the high seat. Say nothing back. Remember it.","I watch the sky with Lofn every evening. Thirty-six winters. No ravens yet. They will come. I am slow but I am not wrong.","The high pasture was the best grazing in Runeheim. Now it is the best view of the Scar. I would rather have the grass.","Weather. Tomorrow will be cold, then clear. You may trust me on weather. On everything else, trust Quartz."],"after":["Lofn rose and looked straight up. No ravens. She said, \"Soon.\" I said, \"Soon.\" We have said it every night since. It is a better word than it was.","Kolbein wants to dye cloth again — grey and gold, he says, for something he has to make. He will not say what.","I have nothing to watch over now but the sky. It is a big job. I am up to it.","The pasture is greening. Lofn has four sheep. Sheep do not care about ravens. It is very restful.","Kolbein said the thing again, about the eye. Then he said, \"Your twin will understand it before you do.\" I hope your twin is clever."],"life":["They call me Tor because I am shaped like a hilltop. Squat, solid, covered in moss on the north side.","I am never wrong about weather. I have been wrong about other things. Mostly about people. In their favour, usually.","I speak slowly. Thinking takes time and I like to do it properly.","Flint sparks, Aster glows, Quartz shines and Heather blooms. I sit. Somebody has to keep the hill down.","I have seen every sunset over the Scar for thirty-six winters. Two hundred of them were very good. Eleven were the best things I have ever seen."],"stage2":["Rain coming. Good rain. The pasture will thank us."],"stage3":["A single raven flew over the high pasture this morning. Not one of the two. Lofn waved at it anyway."],"stage4":["Kolbein has finished dyeing his grey and gold cloth. He is sewing it into a cloak. A cloak for someone tall. He says it is \"for when he comes home\"."],"stage5":["The two ravens came back. Over the hills, crying — but a glad cry now. Lofn stood and laughed. I was not wrong. I am never wrong about the sky."]}},"ember":{"who":"Ember","group":"fairies","realm":4,"fairy":0,"spirits":["Mord","Njal"],"lines":{"before":["Mord was a boy in Askvald. He remembers red, then grey, then chains. That is all. I fill in the rest for him, gently. I leave out the worst.","Njal was on the wrong side of the Ember Wall when it rose. His family was on the other side. In the Grasslands. Alive, he hopes.","I burn as bright as I can, all night, every night, so the ash cannot settle on them. If I go dim, the ash comes. I do not go dim.","Askvald had nine gates and a hundred towers. I kept the stone at the first gate. There are no gates now. There is ash.","If Njal asks you about Stonewick, in the Grasslands — tell him the truth, whatever it is. He has waited long enough."],"after":["Mord asked what the sky looks like now. I told him to look. It was blue. He did not know skies could be blue. He has not stopped looking up.","Njal went to the Grasslands to look for his family. Bramble knew them. She flew him there herself.","I let myself go dim last night for the first time in thirty-six winters. I slept for two days. The ash did not come. There is no more ash to come.","Askvald is still ash. But there is a green thing growing at the first gate. One. Mord found it. He guards it like a dragon.","They do not need me burning any more. I am trying to learn how to just be warm."],"life":["I am Ember because I stayed lit. That is the whole story. It took thirty-six winters to tell.","I am tired in a way that sleep does not fix. I think it is the kind of tired that only stops when you are not needed. I hope I am not needed soon.","Cinder says I show off. Cinder is right. Somebody had to be the brightest thing in the Ashlands.","I have never seen a green field. Ashe has never seen anything green at all. I have seen one moss. I tell her about it.","Askvald's bells were bronze. They melted. I have a drop of one, cooled, in my stone. It still rings if you breathe on it."],"stage2":["I heard there is a waystone in the Wetlands with a fairy who rang bells under water. I would like to meet her. We have a lot in common."],"stage3":["The ash on the plain is thinner. Underneath it is grey earth, not black. Grey is a start."],"stage4":["The Ember Wall is broken. I flew through the gap. On the other side: grass. All of it. Everywhere. I had to sit down."],"stage5":["Askvald has a gate again. Wooden. Small. Mord built it with Njal. The green thing has become a tree. Mord still guards it."]}},"cinder":{"who":"Cinder","group":"fairies","realm":4,"fairy":1,"spirits":["Orm","Ranveig"],"lines":{"before":["Orm was at a birth on the Ash Night. The babe never cried. He has carried that for thirty-six winters. Do not make him tell it twice.","Ranveig heard the fire-giant say a god had promised him the gems. She is a potter. Potters notice what people say over a kiln. Ask her.","I argue with them every night. About pots. About the weather. About whether a Binder has ever had a bath. It keeps them talking.","Brandhavn was the harbour where the gems came in. Every realm's gems. Every ship. Now the harbour is glass.","I am not sad. I am cross. There is a difference. Sad sits down. Cross gets up."],"after":["Orm walked to the Grasslands and sat outside the midwives' house for a long time. Nanna from the Wetlands sat with him. Neither of them spoke.","Ranveig told you about the gems. Good. Now she says she wants to make something beautiful out of clay again, something nobody wants to buy.","I have nobody to argue with. I tried arguing with the stone. It agreed with everything. It was terrible.","Orm asked me if he did everything right, that night. I told him yes. I have never been so sure of anything.","Brandhavn's harbour glass is cracking. Underneath there is water. Real water. Ranveig says a harbour is just water with patience."],"life":["I am Cinder: what is left after the fire, still hot. Touch me and find out.","Cinder-pixies show love by arguing. If I have not argued with you, I do not like you yet. Give it time.","Ember shows off. I tell her so every day. That is love too.","Brandhavn had a thousand ships. I knew the name of every one. Some of them were very silly names.","I am afraid of nothing. Except water. And the dark. And being forgotten. That is three things. I said nothing. I am not good at counting."],"stage2":["The Wetlands fairies sent a message by heron. It says \"hello\" and \"the bells are ringing for you\". The heron was rude. I argued with it. It was lovely."],"stage3":["Ranveig made a bowl. It is crooked and lovely and nobody wants it. She gave it to me. I sleep in it."],"stage4":["The fire-giant's forges are cold. The gems are going home to their realms. Ranveig watched the first cart go. She said, \"Promised. Ha.\""],"stage5":["Orm caught a babe in Brandhavn's new houses last week. She cried at once, loud enough to wake the harbour. Orm cried louder."]}},"ashe":{"who":"Ashe","group":"fairies","realm":4,"fairy":2,"spirits":["Sverri","Thora"],"lines":{"before":["Sverri saw two lights go out above the clouds on the Ash Night. Like eyes closing, he says. He is old. He sees clearly.","Thora forged the chains. They made her. Then they put them on her. She does not want to be forgiven. Forgive her anyway.","I was born that night, in the Wall, from a spark. I have never seen green. Sverri describes grass to me. I think he is exaggerating.","I read a skald's book nine hundred times. I know all about moss. I want to touch it before anyone tells me what it is like.","Emberhold stood right under the Wall. Now it is part of the Wall. Thora says some of the town is in there still. I try not to think about it.","Do not tell me what green is. I want to see it first."],"after":["Thora took the chains off herself. Just held them, and they fell. She dropped them in the ash and walked away and did not look back. Good.","Sverri looked at the sky and said, \"The lights will open again.\" I asked what lights. He just smiled.","They want to show me the Grasslands. I am afraid. What if green is not what the book said?","Thora is forging again. Hinges and nails. \"Things that hold doors open,\" she says. \"Not shut.\"","I went through the Wall. I saw it. Green. I touched moss. It is soft. The book was right. I did not cry. I did. A lot."],"life":["I was born inside a wall of fire. My first sound was a crackle. I am told most fairies start with a song.","I have read one book. Nine hundred times. It is about a skald who loses his harp. He finds it on page two hundred and six. I cry every time.","Ember is the brightest. Cinder is the crossest. I am the newest. I do not know what that makes me yet.","I am made of ash. When I am sad I go grey. When I am happy I go grey with sparks.","Green. I want to see green. If I see green I will know the world is real and not just a book."],"stage2":["A heron flew over the Wall today. It was grey and white and very rude. It was the first thing I have ever seen from the outside."],"stage3":["Sverri is teaching me what sheep are. They are clouds that walk, he says. He is exaggerating. I hope he is not."],"stage4":["I have seen green now. I go through the gap in the Wall every morning to look at it. It is still there every time. I check."],"stage5":["Moss is growing on my stone. On my stone. In the Ashlands. I am not going to scrape it off. Primrose says I must. Primrose is wrong."]}},"soot":{"who":"Soot","group":"fairies","realm":4,"fairy":3,"spirits":["Unn","Vali"],"lines":{"before":["Unn knows something important about the fire and the sky. Ask her. She will say it once. Listen once.","Vali brewed for a feast hall once. Two thrones there were. Now none, and two moons inside, he says. I do not understand it. I remember it.","Nobody notices soot. I sit on the Binders' shoulders and listen. They talk about the fire-giant's temper. It is very bad.","The forest outside Askvald burned in one night. The trunks are still standing, black. I keep my stone among them. It is very quiet.","The Binder at their stone is afraid of birds. I do not know why. I have watched him flinch at a sparrow. Use it."],"after":["Unn walked into the burnt forest and found one seedling. A pine. She sat with it all night.","Vali brewed the first ale in the Ashlands for thirty-six winters. It tasted of smoke. He says the next one will taste of barley.","I do not have to listen to Binders any more. I listen to birds. They talk about much nicer things. Mostly worms.","Unn told you the thing about the fire and the sky? Good. Then you know what to do. I have nothing to add. That is a first.","When they rose, the black trunks creaked. As if the forest remembered being a forest. I think it did."],"life":["I am Soot. I am the smudge on the stone nobody looks at twice. That is how I learn things.","I know more than the other fairies. I do not say so. Saying so would make them notice me.","I sat on a Binder's shoulder for a whole winter once. He never knew. He talked to his chains. He was very lonely. I almost felt sorry for him.","The burnt forest is beautiful at dawn. Black trunks and pink sky. Nobody else thinks so. That is fine. It is mine.","I am not shy. I am careful. There is a difference, and it has kept me alive."],"stage2":["I heard the Binders talking. They are frightened of you. I thought you should know. I thought you should not let it go to your head."],"stage3":["Unn's pine seedling is knee-high to a fairy. That is tall for a fairy. Do not laugh."],"stage4":["The fire-giant's servants are leaving the Ashlands. I watched them go. Some of them looked back. One waved at me. I did not wave back. I nearly did."],"stage5":["The burnt forest is green at the bottom now. The black trunks are still standing, but there are birds in them. They talk about worms. I love it."]}},"pyra":{"who":"Pyra","group":"fairies","realm":4,"fairy":4,"spirits":["Alfhild","Brand"],"lines":{"before":["Alfhild sang that when the cycle breaks, two will come from the water to mend it. She thought it was only a song. I never did.","Brand says to ask the Lady of the Fields where the spring went. I do not know who the Lady is. He does. He will not tell me. He smiles.","I make Alfhild sing the water-song every night. She is tired of it. I am not. Two from the water. I believe it.","The skalds' hall in Askvald had a hearth the size of a house. The sagas were sung there every winter night. I knew them all. I still do.","Brand baked for the skalds. He says a saga is only as good as the bread at it. He is not wrong."],"after":["Alfhild looked at you when she rose. Just looked. Then she said, \"Well. It was not only a song.\" I have never been so happy.","Brand asked me if anyone has found the Lady of the Fields yet. I said not yet. He said, \"Soon.\" He seems very sure. Old bakers usually are.","I made Alfhild sing the water-song one more time. She sang it differently. Slower. As if she was singing it to someone.","The skalds' hall is ash, but Alfhild sang in the ruin of it, and the ash listened. You should have heard it.","Two from the water. I knew. I always knew. I am going to be insufferable about it for a hundred years."],"life":["I am Pyra, the fire-story. I burn brightest when someone is listening.","I believe in prophecies. Not because they are true, but because people make them come true by believing them. Is that not the same thing?","Ember stays lit. Cinder argues. Ashe reads. Soot listens. I tell. Between us we are a whole saga.","I know every saga sung in Askvald. When the hall burned I sang them all to myself so none would be lost. It took three nights.","My favourite saga is the one where nobody dies. It is very short. It is the best one."],"stage2":["Alfhild has started a new verse. She will not let me hear it until it is finished. I have never been so impatient in my life."],"stage3":["Brand made bread in a stone oven in the ruins. The smell went all the way to the Ember Wall. The other fairies came to see what it was."],"stage4":["Alfhild's new verse is about you. It is very long. It is not finished. She says the ending is up to you."],"stage5":["Brand found the Lady of the Fields. He asked her where the spring went. She laughed and pointed at everything. He has not stopped smiling since."]}},"mg_rime_spire":{"who":"Frostwhisper the Rime Witch","group":"mages","realm":1,"fairy":null,"spirits":[],"lines":{"after":["The frost stops at my feet now. Look. I had forgotten that it could. Take the Frost Bolt — and tell the Fernby farms the turnips will be sweet this year."]},"scene":"pn_mg_rime_spire"},"mg_scriptorium":{"who":"Magister Quillon the Arcane Scribe","group":"mages","realm":1,"fairy":null,"spirits":[],"lines":{"after":["My book has turned a page. For the first time in thirty-six years. Look — it is writing about you. Take the spell. I would like to read something new."]},"scene":"pn_mg_scriptorium"},"mg_hearthfire":{"who":"Cindra the Hearth-Witch","group":"mages","realm":1,"fairy":null,"spirits":[],"lines":{"after":["You fought fair and you fought hard. Fire is a hearth before it is a weapon. Remember it, and take the Fireball. My door is open again."]},"scene":"pn_mg_hearthfire"},"mg_rootspire":{"who":"Old Bramblebeard the Thorn Druid","group":"mages","realm":1,"fairy":null,"spirits":[],"lines":{"after":["There. Do you feel that? Something in the roots. A season, coming. I have waited thirty-six years to feel it. Take the Thorns — they guard growing things."]},"scene":"pn_mg_rootspire"},"mg_conductor":{"who":"Voltara the Storm-Caller","group":"mages","realm":2,"fairy":null,"spirits":[],"lines":{"after":["I can put it down. The storm. I did not know I could. Take the Arc Lightning — and call rain with it, sometimes, not only thunder."]},"scene":"pn_mg_conductor"},"mg_frozen_belfry":{"who":"Glacius the Shard Sorcerer","group":"mages","realm":2,"fairy":null,"spirits":[],"lines":{"after":["The bell finished its swing. Did you hear it? Thirty-six years it has been waiting to ring. Take the Ice Storm. I am going to let things melt now."]},"scene":"pn_mg_frozen_belfry"},"mg_mire_tower":{"who":"Mother Morrow the Bog Hex-Witch","group":"mages","realm":2,"fairy":null,"spirits":[],"lines":{"after":["You hit me fair and you did not say sorry. Good. I trust you now. Take the Thunder Storm — and if Quillon asks, I never stole his quill."]},"scene":"pn_mg_mire_tower"},"mg_drowned_lighthouse":{"who":"Tidelord Marenus the Sea-Warlock","group":"mages","realm":2,"fairy":null,"spirits":[],"lines":{"after":["The lamp is out. I can stop now. Thirty-six years I kept it lit under the water. Take the Tidal spell — and if you see a boat on the lake at night, wave it home for me."]},"scene":"pn_mg_drowned_lighthouse"},"mg_ember_observatory":{"who":"Pyrrhia the Nova Sorceress","group":"mages","realm":3,"fairy":null,"spirits":[],"lines":{"after":["I can see new stars again. Small ones. Coming back. I will start the map again tonight. Take the Flame Wave."]},"scene":"pn_mg_ember_observatory"},"mg_hollow_spire":{"who":"Nihilus the Void Warlock","group":"mages","realm":3,"fairy":null,"spirits":[],"lines":{"after":["I have a face again. I can feel it. Strange. Take the Lightning Bolt — use it on the dark, not on people. I did both, once."]},"scene":"pn_mg_hollow_spire"},"mg_lightning_rod":{"who":"Stormhelm the Thunder Magus","group":"mages","realm":3,"fairy":null,"spirits":[],"lines":{"after":["Stand down, you say? Thirty-six years nobody has said it. Thank you. Take the Blizzard. I would like to sit down now."]},"scene":"pn_mg_lightning_rod"},"mg_monolith":{"who":"Gravelord Thane the Stone Shaper","group":"mages","realm":3,"fairy":null,"spirits":[],"lines":{"after":["I can let go of the stone now. It will hold. You saw to that. Take the Spikes — and walk my stairs sometime. They still lead somewhere."]},"scene":"pn_mg_monolith"},"mg_frostbitten_crown":{"who":"Hiemal the Blizzard King","group":"mages","realm":4,"fairy":null,"spirits":[],"lines":{"after":["It is cold, and it is enough. For the first time it is enough. Take the Frost Storm. Use it to cool things, not to stop them."]},"scene":"pn_mg_frostbitten_crown"},"mg_rift_tower":{"who":"Xal'zor the Rift Lich","group":"mages","realm":4,"fairy":null,"spirits":[],"lines":{"after":["The tear is closing. I can feel the edges of myself again. Take the Void Blast. And if you ever need a door — build one. Do not tear it."]},"scene":"pn_mg_rift_tower"},"mg_crimson_spire":{"who":"Lady Vesperine the Soul Drinker","group":"mages","realm":4,"fairy":null,"spirits":[],"lines":{"after":["I am not hungry. For the first time — I am not hungry. Take the Drain. Use it gently. It was for healing, once."]},"scene":"pn_mg_crimson_spire"},"mg_astral_spire":{"who":"Astraeus the Star Sorcerer","group":"mages","realm":4,"fairy":null,"spirits":[],"lines":{"after":["One of the stars on my robe is warm again. Only one. But it is warm. Take the Inferno. I will keep counting — upward now."]},"scene":"pn_mg_astral_spire"}};
